    "editable": true,
    "owner": "snapshot",
    "optionalGroup": "messages.en.BrandFaq",
    "initialValue": "Lumiq Studio creates interactive stories and connected devices for family life. Our products bring reading, play, everyday routines, and shared memories into the moments families spend together."
