    "adminOnly": false,
    "editable": true,
    "owner": "snapshot",
    "optionalGroup": "messages.en.BrandFaq",
    "initialValue": "Children can explore classic stories, become the hero of selected stories with ImagiMe, discover three different endings with Retale, and enjoy LumiqOriginal interactive stories and activities."
